def transform(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    # All task motifs have non-background connected source pixels plus markers.
    # Copy the source motif, preserving offsets from its anchor (top-left).
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (bg,0)]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    pat=[row[c0:c1+1] for row in g[r0:r1+1]]
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==0:
                for i,row in enumerate(pat):
                    for j,v in enumerate(row):
                        rr=r+i-len(pat)//2; cc=c+j-len(pat[0])//2
                        if 0<=rr<h and 0<=cc<w and v not in (bg,0): out[rr][cc]=v
    return out

